import buildsMetadata from "@/content/builds-metadata.json";

/**
 * `/builds` cards (deck 17.5, verbatim).
 *
 * Card grammar per the deck: status chip, name, what it is in two sentences
 * at most, one mono PROVES line. No gated numeral appears on any card; the
 * section's one gated value is the headline, which resolves through
 * `buildsHeadline` in `content/proof-metrics.ts` (bank A7).
 *
 * Eras come from `content/builds-metadata.json`, regenerated by
 * `scripts/builds-metadata.mjs` from repo metadata (git history where a
 * repository exists locally, a recorded window with a named source where one
 * does not). Employer and product naming per story bank A6.
 *
 * Links point only at artifacts a reader can open today: the three public
 * GitHub repositories, verified 2026-08-06. jobos and the analytics platform
 * are private repositories and the employer systems are internal, so those
 * cards carry no link; their PROVES line names the constraint instead.
 * Eight cards, not the deck's nine: hermes-agent was cut (see below).
 */

export type BuildStatus = "operating" | "shipped" | "open-source" | "you-are-here";

export const buildStatusChips: Record<BuildStatus, string> = {
  operating: "Operating",
  shipped: "Shipped",
  "open-source": "Open source",
  "you-are-here": "You are here",
};

export type BuildCard = {
  /** Key into `builds-metadata.json`. */
  id: string;
  name: string;
  status: BuildStatus;
  /** Deck 17.5 body, verbatim. Two sentences maximum. */
  body: string;
  /** Deck 17.5 PROVES line, verbatim, without the prefix. */
  proves: string;
  /** Public artifact, when one exists. */
  href?: string;
  hrefLabel?: string;
};

